import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"Module 12 · DAO governance","description":"","frontmatter":{},"headers":[],"relativePath":"modules/12-dao-governance.md","filePath":"modules/12-dao-governance.md","lastUpdated":1790431304000}'),i={name:"modules/12-dao-governance.md"};function n(r,e,l,h,d,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="module-12-·-dao-governance" tabindex="-1">Module 12 · DAO governance <a class="header-anchor" href="#module-12-·-dao-governance" aria-label="Permalink to &quot;Module 12 · DAO governance&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Contracts</strong></td><td><code>VoteToken.sol</code>, <code>TownGovernor.sol</code>, <code>TownTimelock.sol</code></td></tr><tr><td><strong>Stop</strong></td><td>Council</td></tr><tr><td><strong>Standards</strong></td><td>ERC-20Votes, ERC-6372, OpenZeppelin Governor + TimelockController</td></tr><tr><td><strong>Stamp</strong></td><td>none — governance stamps nobody</td></tr></tbody></table><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Module 11 gave the town a treasury controlled by a handful of named owners. Better than one key, and still a small group deciding for everyone.</p><p>The obvious next step is to let the town vote. Which raises a harder question: <strong>how do you make a vote binding?</strong> A poll is easy. A poll whose result <em>automatically</em> moves the money, with nobody able to ignore it, is a different thing — and it is the only version that counts as governance rather than consultation.</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p>Three contracts with three jobs, and the separation is the design:</p><ul><li><strong>vTVD</strong> (<code>VoteToken</code>) — wraps TVD and records <em>checkpointed</em> balances, so voting power can be measured as it stood at a past moment.</li><li><strong>The Governor</strong> — runs proposals, voting windows, quorum and counting. It holds no money at all.</li><li><strong>The Timelock</strong> — <strong>holds the money</strong>, accepts instructions only from the Governor, and waits before acting on them.</li></ul><p>The Council cannot spend. It can only tell the Timelock to spend, and only after a proposal has actually passed. That indirection is the whole point: a vote is not advice, it is the only route to the treasury.</p><h2 id="key-terms" tabindex="-1">Key terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key terms&quot;">​</a></h2><p><strong>Checkpoint.</strong> A record of a balance at a block or timestamp. Ordinary ERC-20 knows only &quot;now&quot;; voting needs &quot;then&quot;.</p><p><strong>Snapshot.</strong> The moment at which voting power is measured for one proposal — the end of the voting delay. Buying tokens after the snapshot gives you no votes.</p><p><strong>Delegation.</strong> Assigning your voting power to an address. <strong>Tokens that are not delegated count for nobody, including you.</strong> This is the single most common cause of &quot;why did my vote not register&quot;.</p><p><strong>Quorum.</strong> The minimum participation for a vote to count. Trustville uses 4% of wrapped supply, matching common practice — and worth noticing, because 4% is not a democratic threshold by any normal standard.</p><p><strong>Timelock delay.</strong> The waiting period between a proposal passing and executing. It exists so that people who disagree can react — sell, exit, raise the alarm — before it lands.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wrap + delegate ─▸ propose ─▸ [voting delay] ─▸ [voting period] ─▸ queue ─▸ [timelock delay] ─▸ execute</span></span>
<span class="line"><span>                                   ▲                                              ▲</span></span>
<span class="line"><span>                              snapshot taken                             anyone may push the button</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Step</th><th>Call</th><th>Notes</th></tr></thead><tbody><tr><td>Get voting power</td><td><code>depositAndSelfDelegate(amount)</code></td><td>Wrap <strong>and</strong> delegate in one transaction</td></tr><tr><td>Propose</td><td><code>propose(targets, values, calldatas, description)</code></td><td>Threshold is 0 here — anyone may</td></tr><tr><td>Wait</td><td>—</td><td>Voting delay, 60 seconds on Trustville</td></tr><tr><td>Vote</td><td><code>castVote(proposalId, support)</code></td><td>0 against, 1 for, 2 abstain</td></tr><tr><td>Queue</td><td><code>queue(targets, values, calldatas, descriptionHash)</code></td><td>Sends it to the Timelock</td></tr><tr><td>Wait</td><td>—</td><td>Timelock minimum delay</td></tr><tr><td>Execute</td><td><code>execute(targets, values, calldatas, descriptionHash)</code></td><td>Anyone</td></tr></tbody></table><p>Wiring, set at deployment and worth memorising:</p><ul><li><strong>PROPOSER</strong> on the Timelock — the Governor, and nothing else.</li><li><strong>EXECUTOR</strong> — <code>address(0)</code>, meaning anyone may execute a matured proposal.</li><li><strong>ADMIN</strong> — nobody, after the deployer renounces.</li></ul><p>That last line is the one that makes it real. While a deployer still holds the Timelock&#39;s admin role, the DAO is theatre: the admin can schedule whatever they like. Renouncing is the moment governance begins, and it is irreversible.</p><h2 id="the-detail-that-matters" tabindex="-1">The detail that matters <a class="header-anchor" href="#the-detail-that-matters" aria-label="Permalink to &quot;The detail that matters&quot;">​</a></h2><p><strong>Wrapping is not voting power.</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> depositAndSelfDelegate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> amount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">external</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    depositFor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, amount);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    _delegate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This convenience function exists because the two-step version catches out real DAOs constantly. Holders wrap, assume they can vote, and discover at the count that their power was zero. The protocol is behaving correctly; the mental model is wrong. Delegation is explicit by design — it is what lets you lend your voice to someone who follows the proposals more closely than you do.</p><p><strong>The clock is timestamps, not blocks (ERC-6372):</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> clock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> view</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> override</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> returns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint48</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> uint48</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">block</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.timestamp); }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> CLOCK_MODE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> pure</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> override</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> returns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> memory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;mode=timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span></code></pre></div><p>With the default block-number clock, &quot;a ten-minute vote&quot; must be written as a number of blocks, and silently changes length whenever block time changes. On a QBFT chain whose block time you control, that is a foot-gun waiting for the day someone retunes the validators. Timestamps make governance periods mean what they say.</p><p><strong>The snapshot defeats vote-buying by timing.</strong> Voting power is read at the snapshot, so reading a proposal and <em>then</em> acquiring tokens achieves nothing. It does not defeat vote-buying in general — someone who accumulates before proposing has all the power they paid for, which is not a bug but the design.</p><p><strong>One token, one vote.</strong> Say it plainly: this is governance proportional to wealth. The richest holder decides. Delegation, quorum and timelocks soften the edges; none of them change the rule. If that bothers you, good — it should, and &quot;how to govern on chain without plutocracy&quot; is an open problem with a serious literature. Quadratic voting, one-person-one- vote with proof of personhood, conviction voting and reputation systems are all attempts, and none is settled.</p><p><strong>Proposals are identified by their description.</strong> The proposal id is a hash of targets, values, calldatas and <code>keccak256(description)</code>. Change one character of the description at queue or execute time and the id is different, so the call reverts with a state error about a proposal that does not exist. The Trustville UI stores the exact description alongside the id for this reason — after we hit it, hard, in production.</p><h2 id="walk-through-it" tabindex="-1">Walk through it <a class="header-anchor" href="#walk-through-it" aria-label="Permalink to &quot;Walk through it&quot;">​</a></h2><ol><li><strong>Get power.</strong> Approve TVD to the VoteToken, then <code>depositAndSelfDelegate</code>.</li><li>Check <code>getVotes(you)</code>. If it is zero, you skipped the delegation.</li><li><strong>Propose</strong> a payment from the Timelock — target the TVD token, calldata a <code>transfer</code>. Keep the description text; you will need it exactly.</li><li>Check <code>state(proposalId)</code>: <code>Pending</code>. Wait out the voting delay.</li><li><code>Active</code>. Cast votes from several accounts.</li><li>After the voting period: <code>Succeeded</code> — or <code>Defeated</code>, or, if too few voted, <code>Defeated</code> on quorum, which is a good failure to cause on purpose at least once.</li><li><strong>Queue.</strong> Now the Timelock is holding it, and <code>state</code> is <code>Queued</code>.</li><li>Try to execute immediately. It reverts — the delay has not passed.</li><li>Wait, then <strong>execute from a completely different account</strong>. The vote is the authority.</li></ol><p>Then try to break it:</p><ol start="10"><li>Wrap tokens <em>after</em> the snapshot and vote. Your power is zero.</li><li>Propose the same thing twice. The second reverts — same id, already exists.</li><li>Try to make the Timelock pay you directly, without a proposal. There is no path.</li></ol><h2 id="what-actually-happened-on-chain" tabindex="-1">What actually happened on chain <a class="header-anchor" href="#what-actually-happened-on-chain" aria-label="Permalink to &quot;What actually happened on chain&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ProposalCreated(proposalId: 8471…, proposer: 0x…, targets: […], voteStart: …, voteEnd: …, description: &quot;…&quot;)</span></span>
<span class="line"><span>VoteCast(voter: 0x…, proposalId: 8471…, support: 1, weight: 500e18, reason: &quot;&quot;)</span></span>
<span class="line"><span>ProposalQueued(proposalId: 8471…, etaSeconds: …)</span></span>
<span class="line"><span>CallScheduled(id: 0x…, index: 0, target: 0x…, value: 0, data: 0x…, predecessor: 0x0, delay: …)</span></span>
<span class="line"><span>CallExecuted(id: 0x…, index: 0, target: 0x…, value: 0, data: 0x…)</span></span>
<span class="line"><span>ProposalExecuted(proposalId: 8471…)</span></span></code></pre></div><p>Two ids run in parallel: the Governor&#39;s <code>proposalId</code> and the Timelock&#39;s operation <code>id</code>. They are different hashes of overlapping data, and confusing them is a rite of passage. The Governor&#39;s id identifies the <em>vote</em>; the Timelock&#39;s identifies the <em>scheduled call</em>.</p><h2 id="when-a-plain-database-is-better" tabindex="-1">When a plain database is better <a class="header-anchor" href="#when-a-plain-database-is-better" aria-label="Permalink to &quot;When a plain database is better&quot;">​</a></h2><p>Almost every organisation, almost always. A committee with a constitution, minutes and a bank mandate is faster, cheaper, capable of nuance, and can be sued when it goes wrong.</p><p>On-chain governance earns its place when the members <strong>cannot rely on a shared legal system</strong> — pseudonymous, international, no incorporation — or when the thing being governed is itself on chain and the alternative is trusting a small team&#39;s keys. Note how much real DAO activity still runs on off-chain signalling (Snapshot) with a multisig executing, which is a candid admission that full on-chain governance is expensive and slow.</p><h2 id="what-this-does-not-fix" tabindex="-1">What this does not fix <a class="header-anchor" href="#what-this-does-not-fix" aria-label="Permalink to &quot;What this does not fix&quot;">​</a></h2><ul><li><strong>Plutocracy.</strong> As above.</li><li><strong>Voter apathy.</strong> Quorum of 4% exists because 50% is unachievable. Most holders never vote, and a determined 5% can therefore run things.</li><li><strong>Proposal quality.</strong> Nobody checks that calldata does what the description claims. Read the calldata; this is exactly the module 11 memo problem with higher stakes.</li><li><strong>Flash-loan governance attacks.</strong> Snapshots help; a token that can be borrowed before the snapshot is still dangerous. Real incidents exist.</li><li><strong>Speed.</strong> Every delay that protects you also prevents you responding to an emergency. Serious protocols keep an emergency multisig, and then must explain why they have a DAO.</li><li><strong>Legal standing.</strong> A DAO is not a legal person in most jurisdictions, and members may be a general partnership without knowing it.</li></ul><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>Wrapping without delegating.</strong> Zero votes, no error.</li><li><strong>Leaving the Timelock admin assigned.</strong> The DAO is decorative until it is renounced.</li><li><strong>Giving the Governor <code>EXECUTOR</code></strong> and thinking that is tighter. Open execution is deliberate; it stops a queued proposal being held hostage.</li><li><strong>Changing the description string</strong> between propose, queue and execute.</li><li><strong>Quorum too high.</strong> Nothing ever passes and the treasury is frozen.</li><li><strong>Quorum too low.</strong> One holder is the government.</li><li><strong>Voting with the block-number clock on a chain with variable block time</strong>, then wondering why the vote ended early.</li></ul><h2 id="security-checklist" tabindex="-1">Security checklist <a class="header-anchor" href="#security-checklist" aria-label="Permalink to &quot;Security checklist&quot;">​</a></h2><ul><li>[ ] Who holds <code>PROPOSER</code> on the Timelock? Anyone besides the Governor?</li><li>[ ] Has the deployer renounced <code>TIMELOCK_ADMIN_ROLE</code>? Verify it on chain, do not assume.</li><li>[ ] Does the Governor hold funds? It should hold none.</li><li>[ ] Can a proposal change the Timelock&#39;s roles — and should it be able to?</li><li>[ ] What fraction of supply is delegated, and how much does the largest holder control?</li><li>[ ] Can a proposal be executed without being queued?</li><li>[ ] Is the timelock delay long enough for anyone to actually react?</li></ul><h2 id="extend-it" tabindex="-1">Extend it <a class="header-anchor" href="#extend-it" aria-label="Permalink to &quot;Extend it&quot;">​</a></h2><ol><li>Add <code>GovernorPreventLateQuorum</code>, so a proposal that reaches quorum at the last second extends the vote. Work out the attack it prevents.</li><li>Give the Timelock a <code>CANCELLER</code>, then decide who should hold it. You have reinvented the guardian debate that every major protocol has had.</li><li>Replace one-token-one-vote with quadratic voting, and then break it with sybil accounts — which will teach you why nobody has deployed it to a treasury of consequence.</li><li>Make the module 11 treasury a Timelock proposer for emergencies only, and write the governance policy that says when that is legitimate.</li></ol><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://docs.openzeppelin.com/contracts/5.x/governance" target="_blank" rel="noreferrer">OpenZeppelin Governance</a></li><li><a href="https://eips.ethereum.org/EIPS/eip-6372" target="_blank" rel="noreferrer">ERC-6372: contract clock</a></li><li><a href="https://eips.ethereum.org/EIPS/eip-5805" target="_blank" rel="noreferrer">ERC-5805: voting with delegation</a></li><li>Compound&#39;s Governor Bravo, the design everything here descends from.</li><li>Read a post-mortem of a real governance attack — Beanstalk (2022) is the canonical one — and map each step onto the protections above.</li></ul><p><strong>Next:</strong> <a href="./13-charity">Module 13 · Charity →</a></p>`,52)])])}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
